-- Preserve the Cloudflare Email Routing SMTP envelope recipient for inbox queue scoping.

BEGIN;

SET LOCAL lock_timeout = '5s';

ALTER TABLE comms.gmail_messages
    ADD COLUMN IF NOT EXISTS delivered_to_mailbox TEXT;

CREATE INDEX IF NOT EXISTS idx_gmail_messages_delivered_to_mailbox_inbox
    ON comms.gmail_messages (LOWER(delivered_to_mailbox), internal_date DESC)
    WHERE delivered_to_mailbox IS NOT NULL
      AND label_ids LIKE '%INBOX%';

COMMIT;
FOR ALL TO service_role
USING (true)
WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON comms.mail_sync_retry TO service_role;
REVOKE ALL ON comms.mail_sync_retry FROM PUBLIC;
REVOKE ALL ON comms.mail_sync_retry FROM anon;
REVOKE ALL ON comms.mail_sync_retry FROM authenticated;

-- ── 6. Reply linkage on comms.gmail_messages (last: shortest lock) ──────
ALTER TABLE comms.gmail_messages
    ADD COLUMN IF NOT EXISTS in_reply_to text,
    ADD COLUMN IF NOT EXISTS reference_ids text[];

COMMENT ON COLUMN comms.gmail_messages.in_reply_to IS
    'Bare Message-ID from the In-Reply-To header (no angle brackets). Set by mail-sync for mirrored Stalwart Sent rows (ETH-6trgh.2); inbound backfill is ETH-k1gfx. NULL = not a reply, or not yet populated.';
COMMENT ON COLUMN comms.gmail_messages.reference_ids IS
    'Bare Message-IDs from the References header, in header order. Named reference_ids because REFERENCES is reserved. Same population as in_reply_to.';

-- ── Post-conditions ─────────────────────────────────────────────────────
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'comms' AND table_name = 'mail_store_messages'
           AND column_name = 'direction' AND is_nullable = 'NO'
           AND column_default LIKE '%import%'
-- Nullable, no default: metadata-only ADD COLUMN, no table rewrite.
--
-- R19 (data-api impact): NONE. Two nullable columns added; nothing dropped,
--   renamed, or moved. grep workers/data-api/src/routes for gmail_messages:
--   no route selects *, none names these columns.
-- R25: no functions created.
-- R26: comms.gmail_messages is a hot table; ADD COLUMN takes ACCESS
--   EXCLUSIVE briefly, so it runs inside BEGIN/COMMIT with SET LOCAL
--   lock_timeout. No index is built here (the reconciler reads every
--   r2_object_key on each tick already; it is a scan either way).
-- R31: plain ADD COLUMN IF NOT EXISTS replays on the pgdr follower via
--   scripts/ci/supabase-db-push.sh like any other DDL.
-- Grants: app_inbox_rw already holds table-level SELECT/INSERT/UPDATE on
--   comms.gmail_messages (20260618042145), which covers new columns.

BEGIN;

SET LOCAL lock_timeout = '60s';

ALTER TABLE comms.gmail_messages
    ADD COLUMN IF NOT EXISTS merged_r2_object_keys text[],
    ADD COLUMN IF NOT EXISTS merged_mailboxes text[];

COMMENT ON COLUMN comms.gmail_messages.merged_r2_object_keys IS
    'R2 object keys of further deliveries of this same wire Message-ID that were merged into this row instead of inserted (ETH-blie3). The R2 reconciler treats them as present. NULL = none.';
COMMENT ON COLUMN comms.gmail_messages.merged_mailboxes IS
    'Lowercased delivered_to_mailbox of merged deliveries that differ from this row''s own (ETH-blie3). NULL = none.';

DO $$
BEGIN
    IF (SELECT count(*) FROM information_schema.columns
         WHERE table_schema = 'comms' AND table_name = 'gmail_messages'
           AND column_name IN ('merged_r2_object_keys', 'merged_mailboxes')
           AND data_type = 'ARRAY') <> 2 THEN
        RAISE EXCEPTION 'ETH-blie3: merged delivery columns missing or not arrays';
    END IF;
END $$;

COMMIT;

