"""Behaviour: archive_raw_message -- the RFC 822 bytes to R2, once.

Key: ``<prefix><gmail id>.eml`` (workspace: ``ingestion/gmail/<id>.eml``,
the format ``comms.gmail_messages.r2_object_key`` holds). A HEAD first makes
it idempotent: an existing object is never rewritten.
"""

from __future__ import annotations

import hashlib
from base64 import urlsafe_b64decode
from dataclasses import dataclass
from email import message_from_bytes
from email.message import Message
from typing import Any

from .account import MailboxAccount
from .receipts import SKIPPED, WRITTEN, Receipt

BEHAVIOUR = "archive_raw_message"


@dataclass(frozen=True)
class RawMessage:
    """A Gmail ``format=raw`` response, decoded once and shared by every behaviour."""

    gmail: dict[str, Any]
    raw: bytes
    parsed: Message
    sha256: str

    @property
    def id(self) -> str:
        return str(self.gmail["id"])

    @property
    def label_ids(self) -> list[str]:
        return list(self.gmail.get("labelIds", []) or [])


def decode_raw(gmail_msg: dict[str, Any]) -> RawMessage:
    raw = urlsafe_b64decode(gmail_msg["raw"])
    return RawMessage(
        gmail=gmail_msg,
        raw=raw,
        parsed=message_from_bytes(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
    )


def _ascii_metadata(value: str) -> str:
    return "".join(c if c.isprintable() and ord(c) < 128 else "?" for c in value)


def object_exists(r2: Any, bucket: str, key: str) -> bool:
    """HEAD the key. Missing is 404/NoSuchKey on R2 and 400/BadRequest on Garage."""
    try:
        r2.head_object(Bucket=bucket, Key=key)
        return True
    except Exception as err:
        response = getattr(err, "response", {}) or {}
        code = response.get("Error", {}).get("Code", "")
        status = response.get("ResponseMetadata", {}).get("HTTPStatusCode", 0)
        if code in ("404", "NoSuchKey", "400", "BadRequest") or status in (400, 404):
            return False
        raise


def archive_raw_message(
    r2: Any, bucket: str, account: MailboxAccount, msg: RawMessage
) -> Receipt:
    key = account.raw_key(msg.id)
    detail: dict[str, object] = {"key": key, "bytes": len(msg.raw), "sha256": msg.sha256}
    if object_exists(r2, bucket, key):
        return Receipt(BEHAVIOUR, account.slug, msg.id, SKIPPED, {**detail, "reason": "present"})
    r2.put_object(
        Bucket=bucket,
        Key=key,
        Body=msg.raw,
        ContentType="message/rfc822",
        Metadata={
            "message-id": msg.id,
            "sha256": msg.sha256,
            "subject": _ascii_metadata(msg.parsed.get("Subject", "(no subject)")[:255]),
            "from": _ascii_metadata(msg.parsed.get("From", "")[:255]),
        },
    )
    return Receipt(BEHAVIOUR, account.slug, msg.id, WRITTEN, detail)

