"""Behaviour: publish_to_enrichment_queue -- legacy fan-out, OFF by default.

POSTs ``{r2ObjectKey, eventType: "EMAIL", metadata}`` to ``QUEUE_WEBHOOK_URL``
for the old AI enrichment workers. Enabled only by
``GMAIL_SYNC_QUEUE_PUBLISH_ENABLED=true`` (flag name kept from before the
split) AND both ``QUEUE_WEBHOOK_URL`` and ``QUEUE_API_TOKEN`` present.
Failures never stop archiving: R2 is the source of truth.
"""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from typing import Any

from .account import MailboxAccount
from .receipts import DISABLED, FAILED, WRITTEN, Receipt

BEHAVIOUR = "publish_to_enrichment_queue"


@dataclass(frozen=True)
class QueueEndpoint:
    url: str
    token: str


def queue_message(r2_key: str, gmail_msg: dict[str, Any], label_hint: str | None) -> dict:
    labels = gmail_msg.get("labelIds", []) or []
    return {
        "r2ObjectKey": r2_key,
        "eventType": "EMAIL",
        "metadata": {
            "gmailMessageId": gmail_msg.get("id"),
            "gmailThreadId": gmail_msg.get("threadId"),
            "historyId": gmail_msg.get("historyId"),
            "labelIds": labels,
            "internalDate": gmail_msg.get("internalDate"),
            "sizeEstimate": gmail_msg.get("sizeEstimate"),
            "learning_priority": label_hint,
            "is_sent": "SENT" in labels,
            "is_starred": "STARRED" in labels,
            "is_important": "IMPORTANT" in labels,
        },
    }


def publish_to_enrichment_queue(
    post: Callable[..., Any],
    queue: QueueEndpoint | None,
    account: MailboxAccount,
    r2_key: str,
    gmail_msg: dict[str, Any],
    label_hint: str | None = None,
) -> Receipt:
    msg_id = str(gmail_msg.get("id"))
    if not account.publish_enrichment:
        return Receipt(BEHAVIOUR, account.slug, msg_id, DISABLED, {"reason": "flag-off"})
    if queue is None or not queue.url or not queue.token:
        return Receipt(BEHAVIOUR, account.slug, msg_id, DISABLED, {"reason": "no-webhook"})
    try:
        resp = post(
            queue.url,
            json=queue_message(r2_key, gmail_msg, label_hint),
            headers={"Content-Type": "application/json", "Authorization": f"Bearer {queue.token}"},
            timeout=10,
        )
    except Exception as err:
        return Receipt(BEHAVIOUR, account.slug, msg_id, FAILED, {"error": type(err).__name__})
    if resp.status_code == 200:
        return Receipt(BEHAVIOUR, account.slug, msg_id, WRITTEN)
    return Receipt(BEHAVIOUR, account.slug, msg_id, FAILED, {"status": resp.status_code})

